# Try to map each Project_Information to a ProjectName by finding owner/repo strings in the text
def find_project_name(text, candidates):
    # Search for any owner/repo pattern present in the text
    matches = re.findall(r'\b([\w.-]+/[\w.-]+)\b', text)
    for m in matches:
        if m in candidates:
            return m
    return None

